#include <charconv>
#include <iostream>
#include <string_view>

int main() {
    constexpr std::string_view text{"1234"};
    int value = 0;
    const auto result = std::from_chars(text.data(), text.data() + text.size(), value);
    std::cout << value << ", parsed=" << (result.ec == std::errc{} && result.ptr == text.data() + text.size()) << '\n';
}
